xql_query:
// ============================================================
// Rule: Cisco Switch – MAC Flapping alto (≥70 em 10 min)
// Vendor: Cisco
// Objective:
// Detect activity associated with Cisco Switch – MAC Flapping alto (≥70 em 10 min).
// Severity: SEV_040_HIGH
// Category: OTHER
// ============================================================

dataset = cisco_switch_raw
| filter _raw_log contains "%SW_MATM-4-MACFLAP_NOTIF"
| bin _time span = 10m
| comp count() as macflap_10m,
       min(_time) as first_seen,
       max(_time) as last_seen
  by _final_reporting_device_ip, _time
| filter macflap_10m >= 70
| fields _final_reporting_device_ip, _time, macflap_10m, first_seen, last_seen
| sort desc macflap_10m
